-- 04_seed_phenomena.sql  (GENERATED by tools/import_excel.py - do not edit by hand)
-- Source: Rejection_Phinomina.xlsx.  Run in QualityMasterDB after 01 and 03.
-- Idempotent: a (stage, normalized name) that already exists is never inserted again, renamed or deleted.
-- Codes: a new name gets its workbook code (<stage>-NNN) when that code is free. If the code is already used (the
-- workbook gained a row in the middle, or an administrator renamed a seeded phenomenon), the name gets the next free
-- number of its stage instead, under the same per-stage lock the API uses, so a re-run never fails on a duplicate code.
-- The check at the end verifies that every seeded NAME is present. Read docs/DATABASE_RUNBOOK.md before re-running.
SET NOCOUNT ON; SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;   -- sqlcmd starts with QUOTED_IDENTIFIER OFF
BEGIN TRANSACTION;
DECLARE @inserted int = 0, @lock int;
DECLARE @seed TABLE (StageCode nvarchar(30) NOT NULL, Code nvarchar(30) NOT NULL, Name nvarchar(200) NOT NULL, Norm nvarchar(200) NOT NULL);

-- GDC Shop: 25 Excel rows, 25 imported, 0 skipped (duplicate)
SELECT @lock = Id FROM qa.InspectionStages WITH (UPDLOCK, HOLDLOCK) WHERE StageCode = N'GDC_SHOP';   -- same lock as the API's code allocation
WITH missing AS (
    SELECT sd.Code, sd.Name, sd.Norm, s.Id AS StageId,
           CASE WHEN EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode = sd.Code) THEN 1 ELSE 0 END AS Clash
    FROM @seed sd JOIN qa.InspectionStages s ON s.StageCode = sd.StageCode
    WHERE sd.StageCode = N'GDC_SHOP'
      AND NOT EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.InspectionStageId = s.Id AND p.NormalizedName = sd.Norm)),
hi AS (
    SELECT ISNULL(MAX(z.n), 0) AS n FROM (
        SELECT TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) AS n FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode LIKE N'GDC_SHOP-[0-9][0-9][0-9]'
        UNION ALL SELECT TRY_CAST(RIGHT(m.Code, 3) AS int) FROM missing m WHERE m.Clash = 0) z)
SELECT CASE WHEN m.Clash = 0 THEN m.Code
            ELSE N'GDC_SHOP-' + RIGHT(N'000' + CAST(hi.n + ROW_NUMBER() OVER (PARTITION BY m.Clash ORDER BY m.Code) AS nvarchar(10)), 3) END,
       m.Name, m.Norm, m.StageId, 1
FROM missing m CROSS JOIN hi;
SET @inserted += @@ROWCOUNT;

-- CNC Shop: 53 Excel rows, 52 imported, 1 skipped (duplicate)
SELECT @lock = Id FROM qa.InspectionStages WITH (UPDLOCK, HOLDLOCK) WHERE StageCode = N'CNC_SHOP';   -- same lock as the API's code allocation
WITH missing AS (
    SELECT sd.Code, sd.Name, sd.Norm, s.Id AS StageId,
           CASE WHEN EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode = sd.Code) THEN 1 ELSE 0 END AS Clash
    FROM @seed sd JOIN qa.InspectionStages s ON s.StageCode = sd.StageCode
    WHERE sd.StageCode = N'CNC_SHOP'
      AND NOT EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.InspectionStageId = s.Id AND p.NormalizedName = sd.Norm)),
hi AS (
    SELECT ISNULL(MAX(z.n), 0) AS n FROM (
        SELECT TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) AS n FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode LIKE N'CNC_SHOP-[0-9][0-9][0-9]'
        UNION ALL SELECT TRY_CAST(RIGHT(m.Code, 3) AS int) FROM missing m WHERE m.Clash = 0) z)
SELECT CASE WHEN m.Clash = 0 THEN m.Code
            ELSE N'CNC_SHOP-' + RIGHT(N'000' + CAST(hi.n + ROW_NUMBER() OVER (PARTITION BY m.Clash ORDER BY m.Code) AS nvarchar(10)), 3) END,
       m.Name, m.Norm, m.StageId, 1
FROM missing m CROSS JOIN hi;
SET @inserted += @@ROWCOUNT;

-- Pre-treatment Inspection: 34 Excel rows, 34 imported, 0 skipped (duplicate)
SELECT @lock = Id FROM qa.InspectionStages WITH (UPDLOCK, HOLDLOCK) WHERE StageCode = N'PRE_TREATMENT';   -- same lock as the API's code allocation
WITH missing AS (
    SELECT sd.Code, sd.Name, sd.Norm, s.Id AS StageId,
           CASE WHEN EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode = sd.Code) THEN 1 ELSE 0 END AS Clash
    FROM @seed sd JOIN qa.InspectionStages s ON s.StageCode = sd.StageCode
    WHERE sd.StageCode = N'PRE_TREATMENT'
      AND NOT EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.InspectionStageId = s.Id AND p.NormalizedName = sd.Norm)),
hi AS (
    SELECT ISNULL(MAX(z.n), 0) AS n FROM (
        SELECT TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) AS n FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode LIKE N'PRE_TREATMENT-[0-9][0-9][0-9]'
        UNION ALL SELECT TRY_CAST(RIGHT(m.Code, 3) AS int) FROM missing m WHERE m.Clash = 0) z)
SELECT CASE WHEN m.Clash = 0 THEN m.Code
            ELSE N'PRE_TREATMENT-' + RIGHT(N'000' + CAST(hi.n + ROW_NUMBER() OVER (PARTITION BY m.Clash ORDER BY m.Code) AS nvarchar(10)), 3) END,
       m.Name, m.Norm, m.StageId, 1
FROM missing m CROSS JOIN hi;
SET @inserted += @@ROWCOUNT;

-- FINAL Inspection: 34 Excel rows, 34 imported, 0 skipped (duplicate)
SELECT @lock = Id FROM qa.InspectionStages WITH (UPDLOCK, HOLDLOCK) WHERE StageCode = N'FINAL';   -- same lock as the API's code allocation
WITH missing AS (
    SELECT sd.Code, sd.Name, sd.Norm, s.Id AS StageId,
           CASE WHEN EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode = sd.Code) THEN 1 ELSE 0 END AS Clash
    FROM @seed sd JOIN qa.InspectionStages s ON s.StageCode = sd.StageCode
    WHERE sd.StageCode = N'FINAL'
      AND NOT EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.InspectionStageId = s.Id AND p.NormalizedName = sd.Norm)),
hi AS (
    SELECT ISNULL(MAX(z.n), 0) AS n FROM (
        SELECT TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) AS n FROM qa.RejectionPhenomena p WHERE p.PhenomenonCode LIKE N'FINAL-[0-9][0-9][0-9]'
        UNION ALL SELECT TRY_CAST(RIGHT(m.Code, 3) AS int) FROM missing m WHERE m.Clash = 0) z)
SELECT CASE WHEN m.Clash = 0 THEN m.Code
            ELSE N'FINAL-' + RIGHT(N'000' + CAST(hi.n + ROW_NUMBER() OVER (PARTITION BY m.Clash ORDER BY m.Code) AS nvarchar(10)), 3) END,
       m.Name, m.Norm, m.StageId, 1
FROM missing m CROSS JOIN hi;
SET @inserted += @@ROWCOUNT;

-- Audit record of the import (only when this run inserted something; a no-op re-run leaves no audit row)
IF @inserted > 0
    VALUES (NULL, N'EXCEL_IMPORT', N'RejectionPhenomena', NULL, NULL, N'{"GDC_SHOP": {"raw": 25, "imported": 25, "skipped": 0}, "CNC_SHOP": {"raw": 53, "imported": 52, "skipped": 1}, "PRE_TREATMENT": {"raw": 34, "imported": 34, "skipped": 0}, "FINAL": {"raw": 34, "imported": 34, "skipped": 0}}');

-- Post-condition check: abort and roll back unless every seeded (stage, name) is present
-- (LEFT JOIN: a missing stage - 03 not run - must fail, not be skipped)
IF EXISTS (SELECT 1 FROM @seed sd LEFT JOIN qa.InspectionStages s ON s.StageCode = sd.StageCode
           WHERE s.Id IS NULL OR NOT EXISTS (SELECT 1 FROM qa.RejectionPhenomena p WHERE p.InspectionStageId = s.Id AND p.NormalizedName = sd.Norm))
    THROW 50001, N'Seed check failed: some seeded phenomena (or their inspection stages: run 03 first) are missing.', 1;
IF (SELECT COUNT(*) FROM @seed WHERE StageCode = N'GDC_SHOP') <> 25 THROW 50001, N'Seed check failed for GDC_SHOP: the script should hold 25 seeded names', 1;
IF (SELECT COUNT(*) FROM @seed WHERE StageCode = N'CNC_SHOP') <> 52 THROW 50001, N'Seed check failed for CNC_SHOP: the script should hold 52 seeded names', 1;
IF (SELECT COUNT(*) FROM @seed WHERE StageCode = N'PRE_TREATMENT') <> 34 THROW 50001, N'Seed check failed for PRE_TREATMENT: the script should hold 34 seeded names', 1;
IF (SELECT COUNT(*) FROM @seed WHERE StageCode = N'FINAL') <> 34 THROW 50001, N'Seed check failed for FINAL: the script should hold 34 seeded names', 1;
COMMIT TRANSACTION;
PRINT N'Phenomena seed complete.';
